var allImages = input.serpResults || [];

var MIN_WIDTH = 800;
var MIN_HEIGHT = 800;
var ALLOWED_EXTENSIONS = ['.jpg', '.jpeg', '.png', '.webp'];

function hasValidExtension(url) {
    if (!url || typeof url !== 'string') return false;
    var cleanUrl = url.split('?')[0].split('#')[0].toLowerCase();
    for (var i = 0; i < ALLOWED_EXTENSIONS.length; i++) {
        if (cleanUrl.indexOf(ALLOWED_EXTENSIONS[i], cleanUrl.length - ALLOWED_EXTENSIONS[i].length) !== -1) {
            return true;
        }
    }
    return false;
}

function isValidUrl(url) {
    if (!url || typeof url !== 'string') return false;
    if (url.length < 10) return false;
    if (url.indexOf('http') !== 0) return false;

    var blocked = ['gstatic.com','google.com','googleapis.com','bing.com','yahoo.com','favicon','icon','logo','thumbnail','sprite'];
    var lowerUrl = url.toLowerCase();
    for (var i = 0; i < blocked.length; i++) {
        if (lowerUrl.indexOf(blocked[i]) !== -1) return false;
    }
    return true;
}

var filteredImages = [];
for (var i = 0; i < allImages.length; i++) {
    var image = allImages[i];
    var url = image.original || '';
    var width = image.original_width || image.width || 0;
    var height = image.original_height || image.height || 0;

    if (!isValidUrl(url)) continue;
    if (!hasValidExtension(url)) continue;
    if (width < MIN_WIDTH || height < MIN_HEIGHT) continue;

    filteredImages.push(image);
}

var selectedImages = filteredImages.slice(0, 10);

var imageUrls = [];
var imageDimensions = [];
var imageSources = [];

for (var j = 0; j < selectedImages.length; j++) {
    imageUrls.push(selectedImages[j].original || '');
    imageSources.push(selectedImages[j].source || '');
    var w = selectedImages[j].original_width || selectedImages[j].width || 0;
    var h = selectedImages[j].original_height || selectedImages[j].height || 0;
    imageDimensions.push(w + 'x' + h);
}

return {
    images_csv: imageUrls.join(','),
    images_pipe: imageUrls.join('|'),
    image_1: imageUrls[0] || '',
    image_2: imageUrls[1] || '',
    image_3: imageUrls[2] || '',
    image_4: imageUrls[3] || '',
    image_5: imageUrls[4] || '',
    image_6: imageUrls[5] || '',
    image_7: imageUrls[6] || '',
    image_8: imageUrls[7] || '',
    image_9: imageUrls[8] || '',
    image_10: imageUrls[9] || '',
    dimensions_csv: imageDimensions.join(','),
    sources_csv: imageSources.join(','),
    total_found: allImages.length,
    total_valid: filteredImages.length,
    total_selected: selectedImages.length,
    has_images: selectedImages.length > 0,
    filter_summary: 'Found ' + allImages.length + ' total > ' + filteredImages.length + ' passed > ' + selectedImages.length + ' selected'
};

var urls = input.rawImages.split(',');
var handle = input.handle;

var cleanUrls = [];
for (var i = 0; i < urls.length; i++) {
    var url = urls[i].trim();
    if (url && url.length > 10 && url.indexOf('http') === 0) {
        cleanUrls.push(url);
    }
}

return {
    clean_urls: cleanUrls,
    total_images: cleanUrls.length,
    handle: handle
};

