// Build a clean metafields array, skipping any empty values.
// Shopify's productUpdate rejects the WHOLE write if any metafield value is blank
// ("Value can't be blank"), so we must omit empty fields entirely.
var r = input.result || {};
var gtin = (input.gtin == null ? '' : String(input.gtin)).trim();

// [ metafield key , source field on 88.result , type ]
var MAP = [
  ['genere','gender','single_line_text_field'],
  ['disponibilita','availability','single_line_text_field'],
  ['taglia_abbigliamento','size','single_line_text_field'],
  ['lunghezza_snowboard','length','single_line_text_field'],
  ['larghezza_snowboard','snowboard_width','single_line_text_field'],
  ['profilo','snowboard_profile','single_line_text_field'],
  ['shape','shape','single_line_text_field'],
  ['utillizzo','riding_style','single_line_text_field'],
  ['livello','riding_level','single_line_text_field'],
  ['flex','flex','single_line_text_field'],
  ['variant_size','shoe_size_eu','single_line_text_field'],
  ['fit_abbigliamento','fit','single_line_text_field'],
  ['taglia_pantaloni','waist','single_line_text_field'],
  ['lunghezza_l','inseam','single_line_text_field'],
  ['impermeabilita','waterproofing','single_line_text_field'],
  ['traspirabilita','breathability','single_line_text_field'],
  ['isolamento','insulation','single_line_text_field'],
  ['larghezza_tavola_skate','board_width','single_line_text_field'],
  ['diametro_ruote','wheel_diameter','single_line_text_field'],
  ['durezza_ruote','wheel_hardness','single_line_text_field'],
  ['larghezza_truck','truck_width','single_line_text_field'],
  ['wheelbase','truck_height','single_line_text_field'],
  ['concave','concave','single_line_text_field'],
  ['lunghezza_tavola','lunghezza_tavola','single_line_text_field'],
  ['sistema_chiusura_scarponi','sistema_chiusura_scarponi','single_line_text_field'],
  ['disk_compatibilita','disk_compatibilita','single_line_text_field'],
  ['seo_title_original','seo_title_original','single_line_text_field'],
  ['seo_body_original','seo_body_original','multi_line_text_field'],
  ['short_description_en','short_description_en','multi_line_text_field'],
  ['descrizione_breve_it','short_description_it','multi_line_text_field'],
  ['descrizione_breve_fr','short_description_fr','multi_line_text_field'],
  ['descrizione_breve_de','short_description_de','multi_line_text_field'],
  ['descrizione_breve_es','short_description_es','multi_line_text_field'],
  ['meta_title_it','meta_title_it','single_line_text_field'],
  ['meta_title_en','meta_title_en','single_line_text_field'],
  ['meta_title_fr','meta_title_fr','single_line_text_field'],
  ['meta_title_de','meta_title_de','single_line_text_field'],
  ['meta_title_es','meta_title_es','single_line_text_field'],
  ['meta_description_it','meta_description_it','multi_line_text_field'],
  ['meta_descrizione_en','meta_description_en','multi_line_text_field'],
  ['meta_description_fr','meta_description_fr','multi_line_text_field'],
  ['meta_description_de','meta_description_de','multi_line_text_field'],
  ['meta_description_es','meta_description_es','multi_line_text_field']
];

var out = [];
for (var i = 0; i < MAP.length; i++) {
  var key = MAP[i][0], field = MAP[i][1], type = MAP[i][2];
  var v = r[field];
  v = (v == null) ? '' : String(v).trim();
  if (v === '') continue;            // skip empties -> avoids "Value can't be blank"
  out.push({ namespace: 'custom', key: key, value: v, type: type });
}

// gtin: only if present
if (gtin !== '') {
  out.push({ namespace: 'custom', key: 'gtin', value: gtin, type: 'single_line_text_field' });
}

// always flag enrichment done
out.push({ namespace: 'custom', key: 'need_enrichment', value: 'false', type: 'boolean' });

return { metafieldsJson: JSON.stringify(out), count: out.length };

